describe('Browser Back Button Navigation', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should navigate back to previous page without breaking app state', () => {
    // Navigate to a page with multiple steps
    cy.get('[data-testid="step-1"]').should('be.visible');
    cy.get('[data-testid="step-2"]').should('be.visible');
    cy.get('[data-testid="step-3"]').should('be.visible');

    // Verify app state is intact
    cy.get('[data-testid="step-1"]').should('contain', 'Step 1');
    cy.get('[data-testid="step-2"]').should('contain', 'Step 2');
    cy.get('[data-testid="step-3"]').should('contain', 'Step 3');

    // Navigate back using browser back button
    cy.get('[data-testid="back-button"]').click();

    // Verify we are back to step 2
    cy.get('[data-testid="step-1"]').should('not.exist');
    cy.get('[data-testid="step-2"]').should('be.visible');
    cy.get('[data-testid="step-2"]').should('contain', 'Step 2');

    // Verify app state is preserved
    cy.get('[data-testid="step-2"]').should('contain', 'Step 2');
    cy.get('[data-testid="step-3"]').should('not.exist');

    // Verify navigation history is correct
    cy.get('[data-testid="navigation-history"]').should('contain', 'Step 3');
    cy.get('[data-testid="navigation-history"]').should('contain', 'Step 2');
    cy.get('[data-testid="navigation-history"]').should('contain', 'Step 1');
  });

  it('should handle edge case where back button navigates to a non-existent page', () => {
    // Navigate to a page with multiple steps
    cy.get('[data-testid="step-1"]').should('be.visible');
    cy.get('[data-testid="step-2"]').should('be.visible');
    cy.get('[data-testid="step-3"]').should('be.visible');

    // Navigate back twice
    cy.get('[data-testid="back-button"]').click();
    cy.get('[data-testid="back-button"]').click();

    // Verify we are back to step 1
    cy.get('[data-testid="step-2"]').should('not.exist');
    cy.get('[data-testid="step-1"]').should('be.visible');
    cy.get('[data-testid="step-1"]').should('contain', 'Step 1');

    // Verify app state is preserved
    cy.get('[data-testid="step-1"]').should('contain', 'Step 1');
    cy.get('[data-testid="step-2"]').should('not.exist');
    cy.get('[data-testid="step-3"]').should('not.exist');

    // Verify navigation history is correct
    cy.get('[data-testid="navigation-history"]').should('contain', 'Step 3');
    cy.get('[data-testid="navigation-history"]').should('contain', 'Step 2');
    cy.get('[data-testid="navigation-history"]').should('contain', 'Step 1');

    // Verify app state is not broken when navigating to non-existent page
    cy.get('[data-testid="step-1"]').should('be.visible');
    cy.get('[data-testid="step-1"]').should('contain', 'Step 1');
  });
});
